<?php
session_start();
require_once '../middleware/staff.php';
require_once '../config/database.php';
$staffStmt=$pdo->prepare('SELECT e.employee_id,e.department_id,e.firstname,e.lastname FROM employee e WHERE e.user_id=? AND e.employee_type IN ("staff","teacher") LIMIT 1');$staffStmt->execute([$_SESSION['user_id']]);$staff=$staffStmt->fetch(PDO::FETCH_ASSOC);if(!$staff){http_response_code(403);renderPlainErrorAlert('ไม่มีสิทธิ์');}
$calendars=$pdo->query('SELECT calendar_id,academic_year,semester,start_date,end_date FROM internship_calendar WHERE status="active" ORDER BY academic_year DESC,semester')->fetchAll(PDO::FETCH_ASSOC);$selectedId=(int)($_GET['calendar_id']??($calendars[0]['calendar_id']??0));$selected=null;foreach($calendars as $calendar)if((int)$calendar['calendar_id']===$selectedId){$selected=$calendar;break;}
$staff_name=trim($staff['firstname'].' '.$staff['lastname']);$pageHeading='ปฏิทินการศึกษา';$document_count=0;
function h($value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}function thaiDate(?string $date):string{if(!$date)return '-';$months=[1=>'มกราคม',2=>'กุมภาพันธ์',3=>'มีนาคม',4=>'เมษายน',5=>'พฤษภาคม',6=>'มิถุนายน',7=>'กรกฎาคม',8=>'สิงหาคม',9=>'กันยายน',10=>'ตุลาคม',11=>'พฤศจิกายน',12=>'ธันวาคม'];$d=new DateTimeImmutable($date);return(int)$d->format('j').' '.$months[(int)$d->format('n')].' '.((int)$d->format('Y')+543);}
?>
