<section class="mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><form method="get" class="max-w-xl"><label class="block text-sm font-bold text-slate-700">ปีการศึกษาและภาคเรียน<select name="calendar_id" onchange="this.form.submit()" class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3"><option value="">เลือกปฏิทินการศึกษา</option><?php foreach($calendars as $calendar):$term=(int)$calendar['semester']===3?'ภาคฤดูร้อน':'ภาคเรียนที่ '.$calendar['semester'];?><option value="<?=(int)$calendar['calendar_id']?>" <?=(int)$calendar['calendar_id']===$selectedId?'selected':''?>>ปีการศึกษา <?=h($calendar['academic_year'])?> · <?=h($term)?></option><?php endforeach;?></select></label></form><?php if($selected):?><div class="mt-5 grid gap-4 sm:grid-cols-2"><article class="rounded-xl bg-red-50 p-5"><p class="text-sm font-bold text-red-700">วันเปิดภาคเรียน</p><p class="mt-2 text-xl font-black text-slate-900"><?=h(thaiDate($selected['start_date']))?></p></article><article class="rounded-xl bg-slate-100 p-5"><p class="text-sm font-bold text-slate-600">วันปิดภาคเรียน</p><p class="mt-2 text-xl font-black text-slate-900"><?=h(thaiDate($selected['end_date']))?></p></article></div><?php else:?><p class="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">ยังไม่มีปฏิทินการศึกษาที่เปิดใช้งาน กรุณาติดต่อผู้ดูแลระบบ</p><?php endif;?></section>
